#!/usr/bin/env python3
"""Turn 35 Wave 75: THE COMPLETE COACHING ECONOMY - the cost, point and efficiency ladders,
the cost-to-max totals, the effect sizes, the goalkeeper rule, the coach-farming threshold,
the scout discount and probability ladders, the DP boost maxima, and a position-by-position
best-in-game roster.

Wave 75 delivers the numbers the plan has been missing. The centrepiece is the coach
efficiency ladder at a maxed facility: Legendary costs 23.33 gems per development point
against 31.5 for Common, which is the arithmetic behind "buy the best coach you can afford" -
and the reason the corpus's Training-first rule pays for itself.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w75')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_coach=new_ev("r/DreamLeagueSoccer 1hmsicn (26 Dec 2024, the coach cost/point/efficiency ladder at a maxed facility), 1hnll1u (27 Dec 2024, the 90-point max and the cost-to-max totals), 1b4ovuj (2 Mar 2024, the coach counts to max), 1abrrl5 (18 Apr 2024, the effect sizes, the GK rule, the 16-player minimum and the squad totals), 1ajd6pu (5 Feb 2024, the 192-coin threshold), 1pudgh8 (24 Dec 2025, the release-to-coach mapping), 1nmm7sh (21 Sep 2025, the scout probability math), oxprpy and oxahbq (Aug 2021, the DLS21 coach and release nerfs), gamedls.net player stat upgrades (30 Aug 2025, the release-to-coach table), LevelWinner DLS24 guide (15 Mar 2024, the release mapping), ldplayer DLS24 guide (10 Dec 2023, the scout drop rates, the scout discounts and the physio ladder), gamingonphone DLS25 DP guide (27 Dec 2024, the DP boost maxima), gamingonphone DLS26 Career guide (27 Jan 2026, the Legendary-release nerf note), r/DLS 1v16sy2 (20 Jul 2026, the position-by-position best roster), dreamkitsapp.com/data (the Team of 2025, Champion and Dynamic Star ratings), r/DLS 1owdlxx (13 Nov 2025, the +1 special-offer rating observation), z2u and thesoccerera DLS26 top-rated lists",
    "THE COMPLETE COACHING ECONOMY, THE SCOUT LADDERS, THE DP MAXIMA, AND THE BEST-IN-GAME ROSTER. (1) THE COACH COST/POINT/EFFICIENCY LADDER AT A MAXED TRAINING FACILITY - the wave's centrepiece: **Common = 2 points for 63 gems = 31.5 gems per point · Rare = 6 points for 168 gems = 28 gems per point · Legendary = 12 points for 280 gems = 23.33 gems per point.** 'Legendary special coaches are the most financially efficient coaches per gems having the best value per stats.' So the tier you can afford is a genuine efficiency question, not just a speed one. (2) THE COST-TO-MAX TOTALS: 'There is roughly 90 points needed to max a player', giving **45 Common coaches (2,835 gems) · 15 Rare (2,520 gems) · 7.5 Legendary (2,100 gems)** - but with the crucial correction that **normal players need 9 Legendaries, not 7.5** (7.5 applies to special players). (3) THE COACH COUNTS TO MAX: **outfield 80 Common / 20 Rare / 9 Legendary; goalkeepers 20 Common / 10 Rare / 4 Legendary.** A full 16-player squad needs about **142 Legendary / 320 Rare / 1,280 Common**. (4) THE EFFECT SIZES: 'Legendary coaches boost 3 random stats by +3. Rare coaches boost 2 random stats by +2. Common coaches boost 1 random stat by +1.' This reconciles with the 12-point figure once you apply the STR/CON double-weighting - three stats including one Strength can be 3+3+3+3 = 12. (5) THE GOALKEEPER RULE, precise and valuable: 'Legendary coaches increase GKR and GKH by +3, **but only use if GKR > GKH**. Rare coaches increase either GKR or GKH by +2. Common coaches increase either GKR or GKH by +1.' Because a Legendary raises both, using it when GKH is already higher wastes half the value. The recommended GK loop is '1 rare and 4 commons and repeat'. (6) THE CLUB MINIMUM IS 16 PLAYERS: 'Make sure you have 16 players before using coaches, that's the club minimum size and it helps speed up the process.' (7) THE RELEASE-TO-COACH MAPPING, now corroborated by THREE sources: **Common release = 1 Common coach · Rare release = 2 Common coaches · Legendary (80+) release = 1 Rare coach** (gamedls.net, LevelWinner and r/DLS 1pudgh8 all agree). (8) THE NERF HISTORY explains why: the DLS21 update changed it so 'selling a legendary player only gives you a rare coach now, and 2 common coach for selling a rare player', and Legendary coaches dropped from '+5 each' to '+3 each'. A DLS26-era guide notes 'releasing a Legendary player doesn't guarantee a Legendary Coach, so releasing players should be done carefully.' (9) THE COACH-FARMING THRESHOLD, corroborated exactly: releasing a legendary player yields 2 Rare coaches, so '1535:8=192. So you should always save for legendary players when maxing and only buy common players that are 192 coins or less to get most value for your money.' **192 coins brackets the wave-72 '180-210 coin' band - two independent derivations of the same number.** (10) THE SCOUT DROP RATES, second source but with a discrepancy: ldplayer gives Common 93/5/2 (identical to rajatips), Rare 80/15/5 (vs 75/20/5) and Legendary 55/30/15 (vs 40/45/15). The legendary rates match; the ordinary/talented split does not. (11) THE SCOUT DISCOUNT LADDER: **Common 2-4% · Rare 3-5% · Legendary 4-8%** per recruit - the concrete value of the Recruitment Centre. (12) THE SCOUT PROBABILITY MATH, which settles the Common-vs-Legendary debate: a scout yields TWO candidates, so P(at least one legendary) = 1-(1-p)². **Common: 1-(0.98²) = 3.96% · Legendary: 1-(0.85²) = 27.75%** - a ratio of 7.01, while a Legendary scout costs 500c against 75c, i.e. 6.67×. **Legendary scouts are good value, and the 2% Common figure is the correct one.** (13) THE DP BOOST MAXIMA: **Rare Boost = +75%** (max 245 DP in Career, 324 in DLL/Dream Draft) · **Legendary Boost = +150%** (max 350 Career, 463 DLL/Dream Draft). The middle tier conflicts slightly with an earlier +70% figure. (14) THE PHYSIO LADDER CORROBORATED A SECOND TIME: Common +10% energy, Rare +20%, **Legendary +50% and heals all active injuries**. (15) THE BEST-IN-GAME ROSTER BY POSITION (July 2026): CF 86 Haaland/Kane/Dembélé/Mbappé · RW 86 Yamal and Olise · LW 85 Vinícius and Raphinha (or the 96 Nico Williams) · SS 83 Messi · AM 85 Bruno Fernandes · CM 85 Valverde, Pedri, Vitinha · DM 84 Rodri and Çalhanoğlu · LB 84 Nuno Mendes · RB 85 Hakimi · CB 85 Gabriel and Van Dijk · GK Donnarumma. (16) Special-offer cards appear to be pre-trained to base+1: 'Raphinha was trained to 87, Dembélé to 87, Gabriel to 85, Yamal to 86. If you subtract 1 from all of these it leaves you with Raphinha 86, Dembélé 86, Gabriel 84, Yamal 85.' (17) THE LIVE RANK-NAME GAP REMAINS OPEN: a fresh search returned only Rocket League's ladder (Rookie, Semi-Pro, Pro, Veteran, Expert, Master, Legend, Rocketeer), which contaminates results because DLS shares the Intermediate/Pro/Veteran vocabulary. No DLS source names anything above Veteran.",
    "evidence/raw/turn35_w75/EV-489_coaching_economy_and_scout_ladders.html",
    "COACH LADDER at a maxed facility: Common 2 points/63 gems = 31.5 gems per point; Rare 6/168 = 28; LEGENDARY 12/280 = 23.33 - Legendary is the most gem-efficient. COST TO MAX ~90 points: 45 Commons (2,835g), 15 Rares (2,520g), 7.5 Legendaries (2,100g) for special players - but NORMAL players need 9 Legendaries. COUNTS TO MAX: outfield 80 Common/20 Rare/9 Legendary; GK 20/10/4; a 16-player squad ~142/320/1,280. EFFECT SIZES: Legendary 3 stats x +3, Rare 2 x +2, Common 1 x +1 (reconciling the 12-point figure via STR/CON double-weighting). GK RULE: only use a Legendary when GKR > GKH, because it raises both. CLUB MINIMUM 16 PLAYERS. RELEASE-TO-COACH (three sources): Common release = 1 Common coach, Rare release = 2 Commons, Legendary/80+ release = 1 Rare - the result of the DLS21 nerf that also cut Legendary coaches from +5 to +3. COACH-FARMING THRESHOLD 192 COINS (buy at or below), corroborating the 180-210 band. SCOUT DISCOUNTS: Common 2-4%, Rare 3-5%, Legendary 4-8%. SCOUT PROBABILITY: two candidates, so P(at least one legendary) is 3.96% for Common and 27.75% for Legendary - a 7.01x ratio against a 6.67x price ratio, so LEGENDARY SCOUTS ARE GOOD VALUE and the 2% Common figure is correct. DP BOOSTS: Rare +75% (245 Career / 324 DLL+Draft max), Legendary +150% (350 / 463). PHYSIO LADDER corroborated: +10% / +20% / +50% plus all injuries. BEST-IN-GAME ROSTER by position at July 2026. Special-offer cards are pre-trained to base+1. LIVE RANK NAMES above Veteran: still nothing - Rocket League contaminates the search",
    quality="community")

add_claim("THE COACH EFFICIENCY LADDER AT A MAXED TRAINING FACILITY: Common = 2 points for 63 gems (31.5 gems/point) · Rare = 6 points for 168 gems (28/point) · Legendary = 12 points for 280 gems (23.33/point). Legendary is the most gem-efficient coach per point.", 3, "coaching/cost-point-efficiency-ladder", [e_coach], notes="The arithmetic behind buying the best coach you can afford")
add_claim("THE COST TO MAX A PLAYER: ~90 development points, so 45 Common coaches (2,835 gems) · 15 Rare (2,520 gems) · 7.5 Legendary (2,100 gems). BUT normal players need 9 Legendaries, not 7.5 - the 7.5 figure applies to special players.", 3, "coaching/cost-to-max", [e_coach])
add_claim("THE COACH COUNTS TO MAX: outfield 80 Common / 20 Rare / 9 Legendary; goalkeepers 20 Common / 10 Rare / 4 Legendary. A full 16-player squad needs about 142 Legendary / 320 Rare / 1,280 Common.", 3, "coaching/counts-to-max", [e_coach])
add_claim("THE COACH EFFECT SIZES: Legendary boosts 3 random stats by +3 · Rare boosts 2 by +2 · Common boosts 1 by +1. This reconciles the 12-point and 9-point figures once the Strength/Control double-weighting is applied.", 2, "coaching/effect-sizes", [e_coach])
add_claim("THE GOALKEEPER RULE: 'Legendary coaches increase GKR and GKH by +3, but only use if GKR > GKH' - a Legendary raises both, so using it when GKH is already higher wastes half the value. Rare coaches raise either GKR or GKH by +2; Common by +1. The recommended GK loop is '1 rare and 4 commons and repeat'.", 3, "coaching/goalkeeper-coach-rule", [e_coach], notes="Precise and valuable - the corpus had no GK coaching rule")
add_claim("THE CLUB MINIMUM IS 16 PLAYERS: 'Make sure you have 16 players before using coaches, that's the club minimum size and it helps speed up the process.'", 2, "facilities/16-player-club-minimum", [e_coach])
add_claim("THE RELEASE-TO-COACH MAPPING, corroborated by three sources: Common release = 1 Common coach · Rare release = 2 Common coaches · Legendary (80+) release = 1 Rare coach.", 2, "coaching/release-to-coach-three-sources", [e_coach])
add_claim("The nerf history explains the mapping: the DLS21 update changed it so 'selling a legendary player only gives you a rare coach now', and Legendary coaches dropped from '+5 each' to '+3 each'. A DLS26-era guide warns 'releasing a Legendary player doesn't guarantee a Legendary Coach, so releasing players should be done carefully.'", 3, "coaching/nerf-history", [e_coach])
add_claim("THE COACH-FARMING THRESHOLD IS 192 COINS: releasing a legendary player yields 2 Rare coaches, so '1535:8=192... only buy common players that are 192 coins or less to get most value for your money.' This independently corroborates the wave-72 '180-210 coin' band.", 2, "coaching/192-coin-threshold", [e_coach], notes="Two independent derivations of the same number")
add_claim("THE SCOUT DISCOUNT LADDER: Common 2-4% · Rare 3-5% · Legendary 4-8% per recruit - the concrete value of the Recruitment Centre.", 3, "transfers/scout-discount-ladder", [e_coach])
add_claim("THE SCOUT PROBABILITY MATH settles the Common-vs-Legendary debate: a scout yields TWO candidates, so P(at least one legendary) = 1-(1-p)². Common = 1-(0.98²) = 3.96% · Legendary = 1-(0.85²) = 27.75% - a 7.01x ratio against a 6.67x price ratio (75c vs 500c). LEGENDARY SCOUTS ARE GOOD VALUE, and the 2% Common figure is the correct one.", 3, "transfers/scout-two-candidate-probability", [e_coach], notes="Resolves the wave-72 conflict in favour of 2%")
add_claim("A SECOND SOURCE for the scout drop rates, with a discrepancy: Common 93/5/2 (identical) · Rare 80/15/5 (vs 75/20/5) · Legendary 55/30/15 (vs 40/45/15). The legendary rates agree; the ordinary/talented split does not.", 3, "transfers/scout-drop-rates-second-source", [e_coach])
add_claim("THE DP BOOST MAXIMA: Rare Boost = +75% (max 245 DP in Career, 324 in DLL/Dream Draft) · Legendary Boost = +150% (max 350 Career, 463 DLL/Dream Draft). The middle tier conflicts slightly with an earlier +70% figure.", 2, "economy/dp-boost-maxima", [e_coach])
add_claim("THE PHYSIO LADDER CORROBORATED A SECOND TIME: Common +10% energy, Rare +20%, Legendary +50% energy and heals all active injuries.", 2, "medical/physio-ladder-second-source", [e_coach])
add_claim("THE BEST-IN-GAME ROSTER BY POSITION (July 2026): CF 86 Haaland/Kane/Dembélé/Mbappé · RW 86 Yamal and Olise · LW 85 Vinícius and Raphinha (or the 96 Nico Williams) · SS 83 Messi · AM 85 Bruno Fernandes · CM 85 Valverde, Pedri, Vitinha · DM 84 Rodri and Çalhanoğlu · LB 84 Nuno Mendes · RB 85 Hakimi · CB 85 Gabriel and Van Dijk · GK Donnarumma.", 3, "cards/best-in-game-roster-by-position", [e_coach])
add_claim("Special-offer cards appear to be pre-trained to base+1: 'Raphinha was trained to 87, Dembélé to 87, Gabriel to 85, Yamal to 86. If you subtract 1 from all of these it leaves you with Raphinha 86, Dembélé 86, Gabriel 84, Yamal 85.'", 3, "cards/special-offers-pre-trained-plus-one", [e_coach], notes="A way to read next season's ratings early")
add_claim("THE LIVE RANK-NAME GAP REMAINS OPEN: a fresh search returned only Rocket League's ladder (Rookie, Semi-Pro, Pro, Veteran, Expert, Master, Legend, Rocketeer), which contaminates results because DLS shares the Intermediate/Pro/Veteran vocabulary. No DLS source names anything above Veteran.", 2, "dll/rank-names-gap-remains-open", [e_coach], notes="Confirms the gap is genuinely device-only")

for name in ('EV-489_coaching_economy_and_scout_ladders.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
